def contiguous_regions(mask):
    """Find runs of True in a 1-D boolean ``mask``. Returns a list of
    ``(start, end)`` index pairs where ``mask[start:end]`` is all True.
    Standard run-length-encoding over a numpy array.
    """
    m = _np.asarray(mask).astype(bool)
    if m.size == 0:
        return []
    # Pad with False on both sides so the diff catches edges.
    diff = _np.diff(_np.concatenate([[False], m, [False]]).astype(int))
    starts = _np.where(diff == 1)[0]
    ends = _np.where(diff == -1)[0]
    return list(zip(starts.tolist(), ends.tolist()))


def index_of(y):
    """Return ``(x, y)`` where ``x`` is ``range(len(y))`` when ``y``
    is a 1-D sequence. If ``y`` is a pandas DataFrame/Series with an
    index attribute (not a method), returns the index instead. Mirrors
    upstream behaviour used to default the x-axis when only y is
    supplied to plot().
    """
    idx = getattr(y, 'index', None)
    # Only honour .index when it's an array-like attribute, not a
    # method (Python lists have .index() as a method).
    if idx is not None and not callable(idx):
        return _np.asarray(idx), _np.asarray(y)
    arr = _np.atleast_1d(y)
    return _np.arange(len(arr)), arr


def safe_first_element(obj):
    """Return the first element of ``obj`` regardless of whether it's
    a sequence, generator, or numpy scalar. Used to inspect the shape
    of a possibly-iterable argument without consuming a generator.
    """
    try:
        return next(iter(obj))
    except (TypeError, StopIteration):
        return obj


def simple_linear_interpolation(a, steps):
    """Insert ``steps - 1`` linearly-interpolated points between each
    pair of consecutive points in ``a`` (which may be a 1-D or 2-D
    array). Returns the densified array with the same number of axes.
    Used by smoothing pipelines that need extra resolution on a path.
    """
    arr = _np.asarray(a, dtype=float)
    if steps < 2 or len(arr) < 2:
        return arr.copy()
    if arr.ndim == 1:
        # Stretch each segment into `steps` samples.
        out = []
        for i in range(len(arr) - 1):
            seg = _np.linspace(arr[i], arr[i + 1], steps + 1)[:-1]
            out.append(seg)
        out.append(_np.array([arr[-1]]))
        return _np.concatenate(out)
    # 2-D — interpolate per-column.
    cols = []
    for c in range(arr.shape[1]):
        cols.append(simple_linear_interpolation(arr[:, c], steps))
    return _np.stack(cols, axis=1)


def delete_masked_points(*args):
    """Drop rows where any masked array is masked OR any value is NaN.
    Accepts any combination of 1-D arrays / masked arrays / strings.
    Returns the inputs filtered to the surviving rows.
    """
    if not args:
        return args
    # Determine common length, treating strings as scalars passed-through.
    arrays = []
    for a in args:
        if isinstance(a, str):
            arrays.append(None)
            continue
        try:
            arrays.append(_np.asanyarray(a))
        except Exception:
            arrays.append(None)
    n = None
    for a in arrays:
        if a is not None and a.ndim == 1:
            n = len(a) if n is None else min(n, len(a))
    if n is None:
        return args
    keep = _np.ones(n, dtype=bool)
    for a in arrays:
        if a is None or a.ndim != 1:
            continue
        if hasattr(a, 'mask') and a.mask is not _np.ma.nomask:
            keep &= ~_np.asarray(a.mask[:n])
        if _np.issubdtype(a.dtype, _np.floating):
            keep &= ~_np.isnan(a[:n])
    out = []
    for orig, a in zip(args, arrays):
        if a is None or a.ndim != 1:
            out.append(orig)
        else:
            out.append(_np.asarray(a[:n])[keep])
    return out


def is_math_text(s):
    """True when ``s`` looks like a math expression — has an odd number
    of unescaped dollar signs framing the content. Matches the
    `$...$` LaTeX convention. Returns False for non-strings.
    """
    if not isinstance(s, str):
        return False
    # Count unescaped $ — pairs delimit a math span.
    count = 0
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            i += 2
            continue
        if s[i] == '$':
            count += 1
        i += 1
    return count >= 2 and count % 2 == 0


def is_writable_file_like(obj):
    """Check whether ``obj`` quacks like a writable file: has a
    callable ``write`` attribute. Used by savefig to accept
    BytesIO/StringIO/sockets/etc. as ``fname``."""
    return callable(getattr(obj, 'write', None))


def file_requires_unicode(x):
    """Return True if writing to ``x`` requires unicode strings
    (rather than bytes). Inspects the result of a tiny write probe."""
    try:
        x.write(b'')
        return False
    except TypeError:
        return True
    except Exception:
        # Unknown writer — be conservative and assume bytes.
        return False


def open_file_cm(path_or_file, mode='r', encoding=None):
    """Context manager wrapping ``open(path, mode, encoding=...)``
    when given a path, or yielding the object itself when given an
    already-open file. Closes only what it opened."""
    import contextlib, io
    if isinstance(path_or_file, (str, bytes, _os_path_like_check())):
        @contextlib.contextmanager
        def _cm():
            f = open(path_or_file, mode, encoding=encoding)
            try: yield f
            finally: f.close()
        return _cm()

    @contextlib.contextmanager
    def _passthrough():
        yield path_or_file
    return _passthrough()


def _os_path_like_check():
    """Sentinel — returns os.PathLike at import time; isolated to a
    helper so the cbook module doesn't need os at top level."""
    try:
        import os
        return os.PathLike
    except Exception:
        return ()


def print_cycles(objects, outstream=None, show_progress=False):
    """Print reference cycles starting from each object in ``objects``.
    Tiny wrapper over the gc module — used as a debug helper."""
    import gc, sys
    out = outstream or sys.stdout
    for obj in objects:
        refs = gc.get_referrers(obj)
        if not refs: continue
        print(f"cycle root: {type(obj).__name__}@{id(obj):x}", file=out)
        for r in refs[:5]:
            print(f"  referrer: {type(r).__name__}", file=out)


def strip_math(s):
    """Remove ``$...$`` math spans from a string. Used when the
    rendering backend can't handle mathtext and needs a plain-text
    fallback for legend / label text.
    """
    if not isinstance(s, str):
        return s
    out, in_math, i = [], False, 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s):
            if not in_math:
                out.append(s[i:i + 2])
            i += 2
            continue
        if s[i] == '$':
            in_math = not in_math
            i += 1
            continue
        if not in_math:
            out.append(s[i])
        i += 1
    return ''.join(out)


class GrouperView:
    """Read-only view onto a :class:`Grouper`. Implements ``__iter__``
    (groups), ``__contains__`` (membership), ``joined``, and
    ``get_siblings``. Mutating methods (``join``, ``remove``) are
    intentionally absent."""

    def __init__(self, grouper):
        self._g = grouper

    def __contains__(self, item):
        return item in self._g

    def __iter__(self):
        return iter(self._g)

    def joined(self, a, b):
        return self._g.joined(a, b)

    def get_siblings(self, a):
        return self._g.get_siblings(a)


def violin_stats(X, method=None, points=100, quantiles=None):
    """Compute statistics for a violin plot — kernel density estimate,
    medians, quartiles, extrema. ``X`` may be a 1-D array (one violin)
    or a list of arrays (multiple violins). Returns a list of dicts
    keyed by ``coords``, ``vals``, ``mean``, ``median``, ``min``,
    ``max``, ``quantiles``.

    The KDE is approximated with a Gaussian kernel and Silverman's
    rule of thumb for bandwidth selection — matches upstream's default
    behaviour for ``method=None``.
    """
    if not isinstance(X, (list, tuple)) or (X and not hasattr(X[0], '__len__')):
        X = [X]
    out = []
    for xi in X:
        a = _np.asarray(xi, dtype=float)
        a = a[~_np.isnan(a)]
        if a.size == 0:
            out.append({'coords': _np.array([]), 'vals': _np.array([]),
                        'mean': 0.0, 'median': 0.0, 'min': 0.0, 'max': 0.0,
                        'quantiles': []})
            continue
        lo, hi = a.min(), a.max()
        rng = hi - lo
        if rng <= 0:
            coords = _np.array([lo])
            vals = _np.array([1.0])
        else:
            coords = _np.linspace(lo - rng * 0.05, hi + rng * 0.05, points)
            # Silverman bandwidth: 1.06 * std * n^(-1/5)
            h = 1.06 * (a.std() or 1.0) * (a.size ** (-0.2))
            h = max(h, 1e-12)
            # KDE: sum of N(coord; xi, h) over data points
            z = (coords[:, None] - a[None, :]) / h
            vals = _np.exp(-0.5 * z * z).sum(axis=1) / (a.size * h * (2 * _np.pi) ** 0.5)
        if method is not None and callable(method):
            try:
                coords, vals = method(a, coords)
            except Exception:
                pass
        out.append({
            'coords': coords,
            'vals': vals,
            'mean': float(a.mean()),
            'median': float(_np.median(a)),
            'min': float(lo),
            'max': float(hi),
            'quantiles': [float(_np.percentile(a, q * 100))
                          for q in (quantiles or [])],
        })
    return out


