class Stack:
    """A simple navigation stack — used by upstream's ToolViewsPositions
    to maintain the back/forward history of axis view limits. Pushing
    a value drops anything above the current position."""

    def __init__(self, default=None):
        self._items = [default] if default is not None else []
        self._pos = 0 if default is not None else -1

    def __call__(self):
        if 0 <= self._pos < len(self._items):
            return self._items[self._pos]
        return None

    def __len__(self):     return len(self._items)
    def __getitem__(self, idx): return self._items[idx]

    def push(self, value):
        # Drop anything above the current position before pushing.
        self._items = self._items[:self._pos + 1]
        self._items.append(value)
        self._pos = len(self._items) - 1
        return value

    def back(self):
        if self._pos > 0:
            self._pos -= 1
        return self()

    def forward(self):
        if self._pos < len(self._items) - 1:
            self._pos += 1
        return self()

    def clear(self):
        self._items.clear()
        self._pos = -1

    def empty(self):
        return not self._items

    def home(self):
        if self._items:
            self._pos = 0
        return self()

    def remove(self, value):
        try:
            i = self._items.index(value)
            del self._items[i]
            if self._pos >= len(self._items):
                self._pos = len(self._items) - 1
        except ValueError:
            pass


